class OrderMapper {
public:
  void save(const Order& o, pqxx::work& tx) {   // one transaction
    tx.exec("DELETE FROM order_line WHERE order_id = $1", o.id());
    for (const OrderLine& l : o.lines())
      tx.exec("INSERT INTO order_line(order_id, sku, qty) VALUES ($1,$2,$3)",
              o.id(), l.sku(), l.qty());
  }
};
// Order holds std::vector<OrderLine> lines_; no OrderLineMapper exists.

